const body = $input.first().json.body || $input.first().json;
const solicitacao = (body.solicitacao || body.message || '').trim();
if (!solicitacao) throw new Error('Campo "solicitacao" ausente no body da requisição');
return [{ json: { solicitacao } }];

// ─────────────────────────────────────────────
// Nó: Code — Separar SAP codes vs nomes de produtos
// Input: saída da LLM (OpenRouter/Gemma)
// Output: { uf, tipo, sapItems, nameItems, hasSapItems, hasNameItems }
// ─────────────────────────────────────────────

const input = $input.first().json.output;

// ── 1. Extrair o texto da resposta da LLM ────────────────────────────────────
// Suporta resposta já parseada, ou dentro de estruturas OpenAI-compatible
function extractRawText(data) {
  if (data?.itens) return data; // já é o objeto final

  const text =
    data?.message?.content               // OpenRouter padrão
    ?? data?.choices?.[0]?.message?.content
    ?? data?.content
    ?? data?.text
    ?? (typeof data === 'string' ? data : null);

  if (!text) throw new Error('Não foi possível extrair texto da resposta da LLM: ' + JSON.stringify(data));
  return text;
}

// ── 2. Parsear o JSON (com ou sem markdown code fences) ──────────────────────
function parseJson(raw) {
  if (raw !== null && typeof raw === 'object') return raw;

  const cleaned = String(raw)
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (_) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) return JSON.parse(match[0]);
    throw new Error('Falha ao parsear JSON da LLM: ' + cleaned.slice(0, 200));
  }
}

const rawText = extractRawText(input);
const { uf, tipo, itens } = parseJson(rawText);

if (!Array.isArray(itens)) {
  throw new Error('"itens" não é um array: ' + JSON.stringify(itens));
}

// ── 3. Detecção de SAP code ──────────────────────────────────────────────────
// Prefixos que a IA pode adicionar erroneamente
const SAP_PREFIX_RE = /^(s\.?a\.?p\.?|c[óo]d(igo)?\.?\s*sap|sap\s*[:\-\s])\s*/i;

// SAP codes: numéricos puros, tipicamente 5–10 dígitos
const SAP_MIN_DIGITS = 5;
const SAP_MAX_DIGITS = 10;

function looksLikeSap(item) {
  const stripped = item.trim().replace(SAP_PREFIX_RE, '').trim();
  // Após remover prefixo, deve ser somente dígitos no range esperado
  return /^\d+$/.test(stripped) &&
    stripped.length >= SAP_MIN_DIGITS &&
    stripped.length <= SAP_MAX_DIGITS;
}

function extractSapNumber(item) {
  return item.trim()
    .replace(SAP_PREFIX_RE, '')
    .replace(/\D/g, '') // remove qualquer não-dígito residual
    .trim();
}

// ── 4. Classificar cada item ─────────────────────────────────────────────────
const sapItems   = [];
const nameItems  = [];

for (const item of itens) {
  const trimmed = item.trim();
  if (!trimmed) continue;

  if (looksLikeSap(trimmed)) {
    sapItems.push({
      original: trimmed,
      sap: extractSapNumber(trimmed),
    });
  } else {
    nameItems.push({
      original: trimmed,
      searchQuery: trimmed.toUpperCase(), // normaliza para busca vetorial
    });
  }
}

// ── 5. Retorno ───────────────────────────────────────────────────────────────
return [{
  json: {
    uf:           uf   ?? null,
    tipo:         tipo ?? 'pf',
    sapItems,
    nameItems,
    hasSapItems:  sapItems.length > 0,
    hasNameItems: nameItems.length > 0,
    summary: {
      total: itens.length,
      sap:   sapItems.length,
      names: nameItems.length,
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Nó: Selecionar Preço por UF/Tipo
// Input:  itens do Merge (schema normalizado dos dois nodes anteriores)
// Ref:    "Parsear Itens LLM 1" → uf, tipo
// Output: itens prontos para o orçamento com preço já selecionado
// ─────────────────────────────────────────────────────────────────────────────

// ── Tabela de alíquotas ──────────────────────────────────────────────────────
const ICMS_UF = {
  AC: { aliquota: 19.0,  chave_preco: 'icms_20' },
  AL: { aliquota: 20.0,  chave_preco: 'icms_20' },
  AM: { aliquota: 20.0,  chave_preco: 'icms_20' },
  AP: { aliquota: 18.0,  chave_preco: 'icms_18' },
  BA: { aliquota: 20.5,  chave_preco: 'icms_20' },
  CE: { aliquota: 20.0,  chave_preco: 'icms_20' },
  DF: { aliquota: 20.0,  chave_preco: 'icms_20' },
  ES: { aliquota: 17.0,  chave_preco: 'icms_17' },
  GO: { aliquota: 19.0,  chave_preco: 'icms_20' },
  MA: { aliquota: 23.0,  chave_preco: 'icms_20' },
  MT: { aliquota: 17.0,  chave_preco: 'icms_17' },
  MS: { aliquota: 17.0,  chave_preco: 'icms_17' },
  MG: { aliquota: 18.0,  chave_preco: 'icms_18' },
  PB: { aliquota: 20.0,  chave_preco: 'icms_20' },
  PR: { aliquota: 19.5,  chave_preco: 'icms_20' },
  PE: { aliquota: 20.5,  chave_preco: 'icms_20' },
  PI: { aliquota: 22.5,  chave_preco: 'icms_20' },
  RN: { aliquota: 20.0,  chave_preco: 'icms_20' },
  RS: { aliquota: 17.0,  chave_preco: 'icms_17' },
  RJ: { aliquota: 22.0,  chave_preco: 'icms_20' },
  RO: { aliquota: 19.5,  chave_preco: 'icms_20' },
  RR: { aliquota: 20.0,  chave_preco: 'icms_20' },
  SC: { aliquota: 17.0,  chave_preco: 'icms_17' },
  SP: { aliquota: 18.0,  chave_preco: 'icms_18' },
  SE: { aliquota: 20.0,  chave_preco: 'icms_20' },
  TO: { aliquota: 20.0,  chave_preco: 'icms_20' },
};

const UF_PADRAO   = 'SP';
const TIPO_PADRAO = 'pf'; // pf = Pessoa Jurídica (preço de fábrica)

// ── 1. Ler contexto do nó de parsing ────────────────────────────────────────
const parsing = $('Parsear Itens LLM 1').first().json;

const ufRaw = parsing?.uf;
const uf    = (ufRaw && typeof ufRaw === 'string')
  ? ufRaw.trim().toUpperCase()
  : UF_PADRAO;

const tipo = (parsing?.tipo === 'pmc') ? 'pmc' : TIPO_PADRAO;

// ── 2. Resolver chave de ICMS ────────────────────────────────────────────────
const icmsInfo   = ICMS_UF[uf] ?? ICMS_UF[UF_PADRAO];
const chaveIcms  = icmsInfo.chave_preco;  // ex: 'icms_18'
const aliquota   = icmsInfo.aliquota;

// ── 3. Helper: parse de preço brasileiro → número ───────────────────────────
// Os preços vêm como string "93,67" — convertemos para float para cálculos
function parsePreco(str) {
  if (!str || str === '0') return 0;
  return parseFloat(String(str).replace(',', '.')) || 0;
}

// ── 4. Processar cada item do Merge ─────────────────────────────────────────
const produtos = $input.all();
const resultado = [];

for (const item of produtos) {
  const p = item.json;

  // Bloco de preços para a alíquota da UF
  const blocoIcms = p.precos?.[chaveIcms] ?? {};

  const precoPf  = parsePreco(blocoIcms.pf);
  const precoPmc = parsePreco(blocoIcms.pmc);

  // Preço selecionado conforme tipo do cliente
  const precoSelecionado = tipo === 'pmc' ? precoPmc : precoPf;

  // Formata de volta para exibição em pt-BR
  const precoFormatado = precoSelecionado > 0
    ? precoSelecionado.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    : 'Indisponível';

  resultado.push({
    json: {
      // Identificação do produto
      sap:             p.sap,
      nome:            p.nome,
      principio_ativo: p.principio_ativo,
      familia:         p.familia,
      qtde:            p.qtde,
      tarja:           p.tarja,
      ean:             p.ean,

      // Contexto fiscal aplicado
      uf,
      tipo,
      aliquota,
      chave_icms:      chaveIcms,

      // Preços calculados
      preco_pf:        precoPf,
      preco_pmc:       precoPmc,
      preco_aplicado:  precoSelecionado,   // número — bom para cálculos
      preco_formatado: precoFormatado,     // string — bom para exibição

      // Rastreabilidade
      score:           p.score,
      source:          p.source,
    }
  });
}

// Ordena: itens SAP primeiro (source = 'sap'), depois por score desc
resultado.sort((a, b) => {
  if (a.json.source === b.json.source) return b.json.score - a.json.score;
  return a.json.source === 'sap' ? -1 : 1;
});

return resultado;

// ─────────────────────────────────────────────────────────────────────────────
// Nó: Montar Catálogo para Prompt
// Input:  itens do nó "Selecionar Preço por UF/Tipo"
// Output: { catalogo_formatado, mensagem_original, uf, tipo, aliquota }
// ─────────────────────────────────────────────────────────────────────────────

const produtos = $input.all();

// Ajuste o nome do nó conforme o seu fluxo
const mensagemOriginal =
  $('Receber Solicitacao').first().json?.body?.mensagem    // tente variações conforme seu webhook
  ?? $('Receber Solicitacao').first().json?.body?.message
  ?? $('Receber Solicitacao').first().json?.body?.text
  ?? $('Receber Solicitacao').first().json?.mensagem
  ?? $('Receber Solicitacao').first().json?.body?.solicitacao
  ?? '(mensagem não disponível)';

const parsing   = $('Parsear Itens LLM 1').first().json;
const uf        = parsing.uf   ?? 'SP';
const tipo      = parsing.tipo ?? 'pf';

// Pega alíquota do primeiro produto (todos têm a mesma, pois vêm da mesma UF)
const aliquota  = produtos[0]?.json?.aliquota ?? 18;

// ── Rótulo de confiança ──────────────────────────────────────────────────────
function confiancaLabel(p) {
  if (p.source === 'sap')   return 'MAXIMA';   // busca determinística
  if (p.score >= 0.65)      return 'ALTA';
  if (p.score >= 0.50)      return 'MEDIA';
  return 'BAIXA';
}

// ── Formatar cada produto para o catálogo ────────────────────────────────────
const linhasProduto = produtos.map(item => {
  const p = item.json;
  return [
    `Produto: ${p.nome}`,
    `SAP: ${p.sap}`,
    `Principio_Ativo: ${p.principio_ativo ?? 'N/D'}`,
    `Preco: ${p.preco_aplicado.toFixed(2).replace('.', ',')}`,
    `Confianca: ${confiancaLabel(p)}`,
    '---',
  ].join('\n');
});

return [{
  json: {
    catalogo_formatado: linhasProduto.join('\n'),
    mensagem_original:  mensagemOriginal,
    uf,
    tipo,
    aliquota,
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Nó: Montar Resposta Webhook
// Input:  saída da LLM de orçamento
// Ref:    "Selecionar Preço por UF/Tipo" → tabela de preços por SAP
//         "Montar Catálogo para Prompt"  → aliquota
// Output: JSON final do webhook
// ─────────────────────────────────────────────────────────────────────────────

// ── 1. Parsear resposta da LLM ───────────────────────────────────────────────
function parseJsonLLM(data) {
  // Tenta extrair o json da resposta — o nó LLM do n8n geralmente já entrega
  // o content como string dentro de data.message.content ou data.text
  const raw = $input.first().json.output

  if (!raw) throw new Error('Resposta da LLM vazia ou em formato inesperado.');

  const cleaned = String(raw)
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (_) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) return JSON.parse(match[0]);
    throw new Error('LLM não retornou JSON válido: ' + cleaned.slice(0, 300));
  }
}

const llmRaw    = $input.first().json;
const llmOutput = parseJsonLLM(llmRaw);

// ── 2. Montar índice de preços por SAP ──────────────────────────────────────
// Acessa os produtos já com preço selecionado do nó anterior
const precoPorSap  = new Map();
const precoPorNome = new Map();

for (const item of $('Selecionar Preço por UF/Tipo').all()) {
  const p = item.json;
  if (p.sap)  precoPorSap.set(String(p.sap),   p);
  if (p.nome) precoPorNome.set(p.nome.toUpperCase(), p);
}

// ── 3. Dados de contexto ─────────────────────────────────────────────────────
const aliquota = $('Montar Catálogo para Prompt').first().json.aliquota ?? 18;

// ── 4. Helper: busca produto pelo SAP ou nome ────────────────────────────────
function buscarProduto(sap, nome催ogo) {
  if (sap && precoPorSap.has(String(sap))) {
    return precoPorSap.get(String(sap));
  }
  if (nome催ogo) {
    return precoPorNome.get(nome催ogo.toUpperCase()) ?? null;
  }
  return null;
}

// ── 5. Montar itens do orçamento ─────────────────────────────────────────────
const itensLLM    = llmOutput?.itens ?? [];
const itensFinal  = [];
let   totalGeral  = 0;
const alertas     = [];

for (const item of itensLLM) {
  const produto = buscarProduto(item.sap, item.item_catalogo);

  if (!produto) {
    // Produto não encontrado no índice — registra alerta e pula
    alertas.push(`Produto "${item.item_catalogo}" não encontrado na base de preços.`);
    continue;
  }

  const quantidade    = Math.max(1, parseInt(item.item_quantidade) || 1);
  const precoUnitario = produto.preco_aplicado;
  const precoTotal    = parseFloat((precoUnitario * quantidade).toFixed(2));

  totalGeral += precoTotal;

  itensFinal.push({
    item_solicitado: item.item_solicitado,
    item_catalogo:   item.item_catalogo,
    sap:             produto.sap,
    item_preco:      precoUnitario,
    item_quantidade: quantidade,
    item_total:      precoTotal,
    icms:            aliquota,
  });
}

// ── 6. Montar campo "obs" final ───────────────────────────────────────────────
// Combina obs da LLM com alertas técnicos de itens não encontrados
const obsPartes = [];
if (llmOutput?.obs)          obsPartes.push(llmOutput.obs);
if (alertas.length > 0)      obsPartes.push(alertas.join(' '));

let obs = obsPartes.join(' ').trim();
if (!obs) {
  obs = itensFinal.length === 1
    ? 'Orçamento gerado com 1 item.'
    : `Orçamento gerado com ${itensFinal.length} itens.`;
}

// ── 7. Resposta final ────────────────────────────────────────────────────────
return [{
  json: {
    status:           '200',
    orcamento:         itensFinal,
    total_orcamento:  parseFloat(totalGeral.toFixed(2)),
    obs,
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Nó: Tratar Qdrant — busca vetorial
// Input: saída do Loop (itens com { document: { pageContent, metadata }, score })
// Output: itens normalizados, deduplicados por nome, score acima do threshold
// ─────────────────────────────────────────────────────────────────────────────

const SCORE_MIN = 0.40; // abaixo disso é ruído

const allItems = $input.all();

// ── 1. Flatten: cada item pode ser um objeto único ou um array (depende do Loop)
const rawResults = [];

for (const item of allItems) {
  const data = item.json;
  const list = Array.isArray(data) ? data : [data];

  for (const entry of list) {
    // Valida estrutura esperada do Qdrant node
    if (entry?.document?.metadata && typeof entry?.score === 'number') {
      rawResults.push(entry);
    }
  }
}

// ── 2. Filtrar por score mínimo
const filtered = rawResults.filter(r => r.score >= SCORE_MIN);

// ── 3. Deduplicar por nome, mantendo o maior score
//    (mesmo nome pode aparecer com SAPs diferentes — registro_ms distintos,
//     mas preços idênticos; guardamos o de maior score como representante)
const byNome = new Map();

for (const result of filtered) {
  const nome = result.document.metadata.nome;
  const current = byNome.get(nome);

  if (!current || result.score > current.score) {
    byNome.set(nome, result);
  }
}

// ── 4. Normalizar para schema comum
const normalized = [];

for (const [, result] of byNome) {
  const meta = result.document.metadata;

  normalized.push({
    json: {
      sap:             meta.sap             ?? null,
      nome:            meta.nome,
      principio_ativo: meta.principio_ativo ?? null,
      precos:          meta.precos          ?? {},
      score:           result.score,
      source:          'vector',
    }
  });
}

// Ordenar por score descendente para facilitar debug
normalized.sort((a, b) => b.json.score - a.json.score);

return normalized;

// ─────────────────────────────────────────────────────────────────────────────
// Nó: Tratar HTTP Request — busca por SAP (Qdrant scroll API)
// Input: saída do Loop (itens com { result: { points: [...] }, status, time })
// Output: itens normalizados no mesmo schema do Node 1
// ─────────────────────────────────────────────────────────────────────────────

const allItems = $input.all();
const normalized = [];
const seenSaps = new Set(); // evita duplicatas caso o loop envie o mesmo SAP duas vezes

for (const item of allItems) {
  const data = item.json;

  // O loop pode entregar um único objeto ou um array por iteração
  const responses = Array.isArray(data) ? data : [data];

  for (const response of responses) {
    // Descarta respostas com erro ou sem pontos
    if (response?.status !== 'ok') continue;

    const points = response?.result?.points ?? [];

    for (const point of points) {
      const meta = point?.payload?.metadata;
      if (!meta?.sap) continue;

      // Deduplicar por SAP (segurança extra)
      if (seenSaps.has(meta.sap)) continue;
      seenSaps.add(meta.sap);

      normalized.push({
        json: {
          sap:             meta.sap             ?? null,
          nome:            meta.nome,
          principio_ativo: meta.principio_ativo ?? null,
          precos:          meta.precos          ?? {},
          score:           1.0,
          source:          'sap',
        }
      });
    }
  }
}

return normalized;
